() => {
  const sidebar = document.querySelector('[placeholder="搜索"]')?.closest('div');
  // find last items near 内容日
  const all = Array.from(document.querySelectorAll('*')).filter(el => {
    const t = (el.textContent || '').trim();
    return t === '未命名文件夹' || t === '新建文件夹' || t === '文件夹' || t.startsWith('未命名');
  }).slice(0, 20).map(el => ({
    tag: el.tagName,
    text: (el.textContent||'').trim().slice(0,80),
    cls: el.className?.toString?.().slice(0,80),
    contentEditable: el.isContentEditable,
    role: el.getAttribute('role'),
  }));
  // also look for input/textarea focused or near bottom
  const inputs = Array.from(document.querySelectorAll('input,textarea,[contenteditable="true"]')).map(el => ({
    tag: el.tagName,
    value: el.value || el.textContent,
    placeholder: el.getAttribute('placeholder'),
    active: document.activeElement === el,
  }));
  return { all, inputs: inputs.slice(0, 30), active: document.activeElement && {
    tag: document.activeElement.tagName,
    text: (document.activeElement.textContent||'').slice(0,80),
    value: document.activeElement.value,
    contentEditable: document.activeElement.isContentEditable,
  }};
}

