async (page) => {
  // Right-click 异常任务 in sidebar to see context menu
  const target = page.locator('div').filter({ hasText: /^异常任务$/ }).first();
  // find the sidebar item more precisely
  const item = page.getByText('异常任务', { exact: true }).first();
  await item.click({ button: 'right' });
  await page.waitForTimeout(600);
  const menu = await page.evaluate(() => {
    const items = Array.from(document.querySelectorAll('[role="menuitem"], [role="option"], .menu-item, li'))
      .map(el => (el.textContent||'').trim().replace(/\s+/g,' '))
      .filter(t => t && t.length < 40);
    // also any visible popup texts
    const pop = Array.from(document.querySelectorAll('[class*="menu"], [class*="popup"], [class*="dropdown"]'))
      .filter(el => {
        const r = el.getBoundingClientRect();
        return r.width > 50 && r.height > 30 && r.bottom > 0;
      })
      .map(el => (el.innerText||'').slice(0, 500));
    return { items: [...new Set(items)].slice(0, 40), pop: pop.slice(0, 5) };
  });
  return menu;
}

