async (page) => {
  // Escape any open menus, snapshot sidebar store folders
  await page.keyboard.press('Escape');
  await page.waitForTimeout(200);
  await page.keyboard.press('Escape');
  await page.waitForTimeout(300);
  const side = await page.evaluate(() => {
    // collect sidebar leaf-ish texts in order
    const search = document.querySelector('input[placeholder="搜索"]');
    let root = search;
    for (let i=0;i<12 && root;i++) root = root.parentElement;
    const texts = [];
    const walk = (el) => {
      if (!el) return;
      for (const c of el.children) {
        const t = (c.innerText||'').trim();
        // only direct short labels
        if (c.children.length <= 3) {
          const leaf = (c.textContent||'').trim().replace(/\s+/g,' ');
          if (leaf && leaf.length < 40 && !texts.includes(leaf) && !leaf.includes('\n')) texts.push(leaf);
        }
        walk(c);
      }
    };
    // simpler: get all short unique lines near left panel
    const all = Array.from(document.querySelectorAll('body *'))
      .filter(el => {
        const r = el.getBoundingClientRect();
        return r.left < 320 && r.width > 40 && r.width < 300 && r.height > 16 && r.height < 40 && r.top > 100;
      })
      .map(el => ({t:(el.textContent||'').trim().replace(/\s+/g,' '), top: Math.round(el.getBoundingClientRect().top), left: Math.round(el.getBoundingClientRect().left)}))
      .filter(x => x.t && x.t.length < 36 && x.left < 280);
    // dedupe by text keeping order by top
    const seen = new Set();
    const ordered = [];
    for (const x of all.sort((a,b)=>a.top-b.top || a.left-b.left)) {
      if (seen.has(x.t)) continue;
      // skip pure icons/numbers
      if (/^\d+$/.test(x.t)) continue;
      seen.add(x.t);
      ordered.push(x.t);
    }
    return ordered.slice(-40);
  });
  return { side };
}

